cells={(r,c) for r,cs in {0:range(2,6),1:range(2,6),2:range(1,6),3:range(0,6),4:range(1,6),5:range(1,6)}.items() for c in cs}
start=frozenset({(3,3),(4,1),(4,2),(4,5),(5,1)})
def moves(s):
 for a in s:
  r,c=a
  for dr,dc in [(2,0),(-2,0),(0,2),(0,-2)]:
   b=(r+dr,c+dc); m=(r+dr//2,c+dc//2)
   if b in cells and m in cells:
    ns=(s-{a,m})|{b}
    yield a,b,frozenset(ns)
q=deque([start]); prev={start:None}; pm={}
goal=None
while q:
 s=q.popleft()
 if len(s)==1: goal=s;break
 for a,b,ns in moves(s):
  if ns not in prev:
   prev[ns]=s;pm[ns]=(a,b);q.append(ns)
path=[]
while prev[goal] is not None:
 path.append(pm[goal]);goal=prev[goal]
path=path[::-1]
len(path),path

